//! The architecture table: every property of every architecture, stated once.
//!
//! One block per architecture, generated by [`arch_table!`] into the
//! [`TargetArchitecture`] enum, [`TargetArchitecture::spec`], [`TargetArchitecture::all`],
//! the `Display` spelling and the `FromStr` spellings. Nothing about an architecture is
//! stated anywhere else, so adding one is one block and adding a property is one field.
//!
//! The compiler enforces both halves of that. A block missing a field does not match the
//! macro's entry rule, so an architecture cannot exist without every property; the
//! generated `spec` match has no wildcard arm; and `all` and the target list are derived
//! from the same table, so they cannot fall behind it.

use crate::arch_variant::{
    Aarch64Level, ArchVariant, Armv7Variant, PowerLevel, RiscvIsa, VariantAxis,
};
use crate::cpu_level::X86CpuLevel;
use crate::environment::TargetEnvironment;

/// Width of a data pointer. Pointer size and alignment derive from it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum PointerWidth {
    Bits32,
    Bits64,
    Bits128,
}

impl PointerWidth {
    pub const fn bytes(self) -> usize {
        match self {
            Self::Bits32 => 4,
            Self::Bits64 => 8,
            Self::Bits128 => 16,
        }
    }
}

/// Byte order of multi-byte values in memory.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Endianness {
    Little,
    Big,
}

/// What a finished compilation of this target is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum OutputArtifact {
    /// Object files that a linker turns into an executable.
    Executable,
    /// A self-contained module, assembled but never linked.
    Module,
    /// Assembly text handed on as-is.
    Text,
}

/// Size and alignment, in bytes, of the `va_list` an architecture's C ABI defines.
///
/// A `va_list` is a struct the ABI names field by field, so its size is a property of
/// the architecture and not of the pointer width. The shapes stated in the table are:
///
/// - x86_64: System V AMD64 ABI §3.5.7, `struct { unsigned int gp_offset, fp_offset;
///   void *overflow_arg_area, *reg_save_area; }` — 24 bytes.
/// - aarch64: AAPCS64 (IHI 0055) appendix "Variable Argument Lists", `struct { void
///   *__stack, *__gr_top, *__vr_top; int __gr_offs, __vr_offs; }` — 32 bytes.
/// - s390x: zSeries ELF ABI supplement, `struct { long __gpr, __fpr; void
///   *__overflow_arg_area, *__reg_save_area; }` — 32 bytes.
/// - riscv, powerpc64 ELFv2, loongarch, mips n64, wasm: a plain `void *`, one pointer.
/// - i686: Intel386 psABI §3.17, `char *` — 4 bytes.
/// - 32-bit ARM: AAPCS (IHI 0042) §7.1, `struct __va_list { void *__ap; }` — 4 bytes.
///
/// [`VaListAbi::Undefined`] is a statement that no ABI defines one, not an omission.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum VaListAbi {
    Defined { size: u64, alignment: u64 },
    Undefined,
}

impl VaListAbi {
    pub const fn of(size: u64, alignment: u64) -> Self {
        Self::Defined { size, alignment }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum FloatAggregateAbi {
    Refused,
    SysV,
    Aapcs64,
    Win64,
}

/// The facts a target-independent lowering needs to turn IR into MIR.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct TargetDataLayout {
    pub pointer_width: PointerWidth,
    pub int_register_bits: u32,
    pub endianness: Endianness,
    pub va_list: VaListAbi,
    pub float_aggregates: FloatAggregateAbi,
}

impl TargetDataLayout {
    pub const fn has_64bit_int_registers(self) -> bool {
        self.int_register_bits >= 64
    }
}

/// The ELF interpreter an architecture takes, one path per environment it supports.
///
/// `None` is a statement that the combination has no interpreter, not an omission.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct LinuxInterpreters {
    /// glibc, with the architecture's own floating-point ABI.
    pub gnu: Option<&'static str>,
    /// glibc, with the soft-float ABI. Reached by `eabi` and by a RISC-V ISA without `d`.
    pub gnu_soft_float: Option<&'static str>,
    /// musl libc.
    pub musl: Option<&'static str>,
    /// Lamina's own C library. `None` on every architecture today: no Lamina libc has
    /// been written, so there is no loader to name. A port fills this in here.
    pub lamina: Option<&'static str>,
}

/// Cross-toolchain triples, by C library.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ToolchainTriples {
    pub gnu: Option<&'static str>,
    pub musl: Option<&'static str>,
    /// Lamina's own toolchain. `None` on every architecture today: nothing outside this
    /// repository supplies a Lamina-libc cross compiler, and nothing should be guessed.
    pub lamina: Option<&'static str>,
}

/// Everything an architecture states about itself.
///
/// Read it through [`crate::Target::spec`], which applies the variant's refinements;
/// [`TargetArchitecture::spec`] is the unrefined form the table states.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ArchSpec {
    /// Canonical spelling, the one `Display` writes.
    pub token: &'static str,
    /// Further spellings `FromStr` accepts for this architecture.
    pub spellings: &'static [&'static str],
    /// Target strings this architecture contributes to the supported-target list.
    pub targets: &'static [&'static str],
    pub pointer_width: PointerWidth,
    /// Widest integer one register holds. Not the pointer width: wasm32 has 32-bit
    /// pointers and 64-bit integer registers.
    pub max_int_register_bits: u32,
    pub endianness: Endianness,
    /// Size and alignment of this architecture's C `va_list`.
    pub va_list: VaListAbi,
    /// Alignment the stack pointer holds at a call. `1` means there is no machine stack.
    pub stack_alignment_at_call: usize,
    /// Whether an argument with 16-byte alignment starts at its own alignment rather than
    /// at the next word. AAPCS64 rounds the integer register counter up to even before
    /// such an argument; the riscv psABI makes that rule variadic-only and ppc64 does not
    /// round for named arguments either.
    pub honors_argument_alignment: bool,
    pub float_aggregates: FloatAggregateAbi,
    pub output_artifact: OutputArtifact,
    /// Environment a hosted target of this architecture means when the target string
    /// names none.
    pub hosted_environment: TargetEnvironment,
    /// Environments a target string may name for this architecture, beside
    /// [`TargetEnvironment::Freestanding`], which every architecture accepts.
    pub environments: &'static [TargetEnvironment],
    pub interpreters: LinuxInterpreters,
    pub toolchain: ToolchainTriples,
    /// Directory name under the Windows SDK `Lib` tree. `None` means Windows has no
    /// library layout for this architecture, and asking for one is an error rather than
    /// a search of the x86_64 directories.
    pub msvc_library_arch: Option<&'static str>,
    /// The sub-architecture axis this architecture has, and its default.
    pub variants: VariantAxis,
}

impl ArchSpec {
    pub const fn data_layout(&self) -> TargetDataLayout {
        TargetDataLayout {
            pointer_width: self.pointer_width,
            int_register_bits: self.max_int_register_bits,
            endianness: self.endianness,
            va_list: self.va_list,
            float_aggregates: self.float_aggregates,
        }
    }

    pub const fn has_64bit_int_registers(&self) -> bool {
        self.max_int_register_bits >= 64
    }

    /// The ELF interpreter for an environment, or `None` when there is none.
    pub const fn interpreter(&self, environment: TargetEnvironment) -> Option<&'static str> {
        match environment {
            TargetEnvironment::Gnu | TargetEnvironment::Eabihf => self.interpreters.gnu,
            TargetEnvironment::Eabi => self.interpreters.gnu_soft_float,
            TargetEnvironment::Musl => self.interpreters.musl,
            TargetEnvironment::Lamina => self.interpreters.lamina,
            TargetEnvironment::Freestanding => None,
        }
    }

    /// The cross-toolchain triple for an environment.
    pub const fn toolchain_triple(&self, environment: TargetEnvironment) -> Option<&'static str> {
        match environment {
            TargetEnvironment::Gnu | TargetEnvironment::Eabi | TargetEnvironment::Eabihf => {
                self.toolchain.gnu
            }
            TargetEnvironment::Musl => self.toolchain.musl,
            TargetEnvironment::Lamina => self.toolchain.lamina,
            TargetEnvironment::Freestanding => self.toolchain.gnu,
        }
    }

    /// Whether a target string may name this environment for this architecture.
    pub fn accepts_environment(&self, environment: TargetEnvironment) -> bool {
        environment == TargetEnvironment::Freestanding || self.environments.contains(&environment)
    }
}

macro_rules! arch_table {
    ($(
        $(#[doc = $doc:literal])*
        $(#[cfg($cfg:meta)])?
        $variant:ident {
            token: $token:literal,
            spellings: [$($spelling:literal),* $(,)?],
            targets: [$($target:literal),* $(,)?],
            pointer_width: $pointer_width:ident,
            max_int_register_bits: $int_bits:literal,
            endianness: $endianness:ident,
            va_list: $va_list:expr,
            stack_alignment_at_call: $stack_align:literal,
            honors_argument_alignment: $honors:literal,
            float_aggregates: $float_aggregates:ident,
            output_artifact: $artifact:ident,
            hosted_environment: $hosted:ident,
            environments: [$($environment:ident),* $(,)?],
            interpreters: {
                gnu: $i_gnu:expr,
                gnu_soft_float: $i_soft:expr,
                musl: $i_musl:expr,
                lamina: $i_lamina:expr
            },
            toolchain: { gnu: $t_gnu:expr, musl: $t_musl:expr, lamina: $t_lamina:expr },
            msvc_library_arch: $msvc:expr,
            variants: $axis:expr,
        }
    )*) => {
        /// An architecture lamina has a backend for, or has reserved a name for.
        ///
        /// Every property is stated in the table in [`crate::arch_table`]; there are no
        /// per-property matches anywhere else.
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        pub enum TargetArchitecture {
            $(
                $(#[doc = $doc])*
                $(#[cfg($cfg)])?
                $variant,
            )*
        }

        impl TargetArchitecture {
            /// Everything this architecture states about itself.
            pub const fn spec(self) -> ArchSpec {
                match self {
                    $(
                        $(#[cfg($cfg)])?
                        Self::$variant => ArchSpec {
                            token: $token,
                            spellings: &[$($spelling),*],
                            targets: &[$($target),*],
                            pointer_width: PointerWidth::$pointer_width,
                            max_int_register_bits: $int_bits,
                            endianness: Endianness::$endianness,
                            va_list: $va_list,
                            stack_alignment_at_call: $stack_align,
                            honors_argument_alignment: $honors,
                            float_aggregates: FloatAggregateAbi::$float_aggregates,
                            output_artifact: OutputArtifact::$artifact,
                            hosted_environment: TargetEnvironment::$hosted,
                            environments: &[$(TargetEnvironment::$environment),*],
                            interpreters: LinuxInterpreters {
                                gnu: $i_gnu,
                                gnu_soft_float: $i_soft,
                                musl: $i_musl,
                                lamina: $i_lamina,
                            },
                            toolchain: ToolchainTriples {
                                gnu: $t_gnu,
                                musl: $t_musl,
                                lamina: $t_lamina,
                            },
                            msvc_library_arch: $msvc,
                            variants: $axis,
                        },
                    )*
                }
            }

            /// Every architecture in the table, in declaration order.
            pub fn all() -> Vec<Self> {
                let mut architectures = Vec::new();
                $(
                    $(#[cfg($cfg)])?
                    architectures.push(Self::$variant);
                )*
                architectures
            }

            /// The architecture a bare spelling names, without consulting the refusals.
            pub(crate) fn from_spelling(spelling: &str) -> Option<Self> {
                $(
                    $(#[cfg($cfg)])?
                    if spelling == $token $(|| spelling == $spelling)* {
                        return Some(Self::$variant);
                    }
                )*
                None
            }
        }
    };
}

